Object.assign(LANG_EN,{"ctOS INSTALADO": "ctOS INSTALLED", "celular › ctOS": "phone › ctOS", "ctOS · SEM REDE AQUI": "ctOS · NO NETWORK HERE", "JAMMER · JÁ ESTÁ ATIVO": "JAMMER · ALREADY ACTIVE", "ctOS · PONTE LEVADIÇA": "ctOS · DRAWBRIDGE", "erguendo a ponte": "raising the bridge", "ctOS · A PONTE JÁ ESTÁ SE MOVENDO": "ctOS · THE BRIDGE IS ALREADY MOVING", "ctOS · SEMÁFOROS VERDES": "ctOS · ALL LIGHTS GREEN", "todo mundo acelera no cruzamento": "everyone floors it at the crossing", "ctOS · SEMÁFOROS NORMAIS": "ctOS · LIGHTS BACK TO NORMAL", "APAGAR · VOLTAR": "DELETE · BACK", "Instale o app ctOS": "Install the ctOS app", "loja de armas · o bloqueador vem no celular": "gun store · the jammer lives on your phone", "ctOS instalado. O bloqueador agora mora no celular.": "ctOS installed. The jammer lives on my phone now.", "entre no banco · celular › ctOS › JAMMER": "go into the bank · phone › ctOS › JAMMER", "APP ctOS INSTALADO": "ctOS APP INSTALLED", "instala o app ctOS (jammer e perfil de pedestres no celular)": "installs the ctOS app (jammer and pedestrian profiles on the phone)", "armas 3: + bazuca, lança-chamas, granada e bomba remota": "weapons 3: + bazooka, flamethrower, grenade and remote bomb", "na roda de armas, última fatia ›": "in the weapon wheel, last slot ›", "Motorista usa pistola, Magnum ou metralhadora;": "Driver uses pistol, Magnum or SMG;"});
